#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// Common PolyBench-style definitions (DATA_TYPE, etc.)
#include "defines.hpp"

// Benchmark-specific definitions (N, TSTEPS, etc.)
#include "adi.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/*
 * Initialize array u:
 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       u[i][j] = (DATA_TYPE)(i + n - j) / n;
 *
 * C array u[i][j] is mapped to Halide Buffer u(j, i).
 *
 * Here we implement the initialization as a Halide pipeline and
 * schedule it for vectorization and parallelization.
 */
static void init_array(int n, Halide::Buffer<num_t, 2> u) {
    Var x("x"), y("y"); // x == j (fast), y == i (slow)
    Func init_u("init_u");

    // u[i][j] = (i + n - j) / n  ==>  u(j, i) = ...
    // Remember: Buffer is indexed as (x=j, y=i) here.
    Expr n_expr = cast<num_t>(n);
    init_u(x, y) = (cast<num_t>(y + n - x)) / n_expr;

    // Simple schedule: vectorize along x (fast dim), parallelize along y.
    Target target = get_jit_target_from_environment();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) {
        // Reasonable fallback if natural_vector_size() returns 0.
        vec_width = std::is_same<num_t, float>::value ? 8 : 4;
    }
    init_u.vectorize(x, vec_width).parallel(y);

    init_u.realize(u);
}

/*
 * Main computational kernel translated to C++ operating on Halide::Buffer.
 *
 * Original signature:
 *
 *   void kernel_adi(int tsteps, int n,
 *                   DATA_TYPE u[N][N],
 *                   DATA_TYPE v[N][N],
 *                   DATA_TYPE p[N][N],
 *                   DATA_TYPE q[N][N]);
 *
 * Mapping of C indices A[i][j] -> Buffer A(j, i):
 *   - C A[i][j]     == buf(j, i)
 *   - buf(x, y)     == A[y][x]
 *
 * We preserve the original ADI algorithm and loop structure, but:
 *   - Hoist all scalar constants.
 *   - Introduce OpenMP parallelism across the independent i-lines.
 *   - Use Halide pipelines to precompute the stencil-like numerators
 *     that appear in the q-updates in both the column sweep and row sweep.
 *     These precomputations are purely local stencils (no recurrences),
 *     so Halide can optimize them (vectorize + parallelize) effectively.
 *   - The sequential tridiagonal solves (forward/back substitution
 *     along j) remain explicit C++ loops, since they have loop-carried
 *     dependencies that are not a good fit for Halide's pure functional
 *     update model.
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> u,
                       Halide::Buffer<num_t, 2> v,
                       Halide::Buffer<num_t, 2> p,
                       Halide::Buffer<num_t, 2> q) {
    // ------------------------------------------------------------------
    // Scalar parameters (identical to original code, just slightly
    // cleaned up and with a few useful precomputations).
    // ------------------------------------------------------------------
    const num_t one = num_t(1.0);
    const num_t two = num_t(2.0);

    const num_t DX   = one / num_t(n);
    const num_t DY   = one / num_t(n);
    const num_t DT   = one / num_t(tsteps);
    const num_t B1   = num_t(2.0);
    const num_t B2   = num_t(1.0);
    const num_t mul1 = B1 * DT / (DX * DX);
    const num_t mul2 = B2 * DT / (DY * DY);

    const num_t a = -mul1 / num_t(2.0);
    const num_t b = one + mul1;
    const num_t c = a;
    const num_t d = -mul2 / num_t(2.0);
    const num_t e = one + mul2;
    const num_t f = d;

    const num_t one_plus_2d = one + two * d;
    const num_t one_plus_2a = one + two * a;

    // ------------------------------------------------------------------
    // Halide setup for precomputing the q numerators as 2D stencils.
    //
    // Column sweep:
    //   num_col(i,j) = -d * u[i-1][j]
    //                  + (1 + 2*d) * u[i][j]
    //                  - f * u[i+1][j]
    //
    // Under mapping A[i][j] -> u_buf(j, i) == u_buf(x, y) with:
    //   A[i-1][j] == u_buf(j, i-1) == u_buf(x = i-1, y = j)
    //   A[i][j]   == u_buf(j, i)   == u_buf(x = i,   y = j)
    //   A[i+1][j] == u_buf(j, i+1) == u_buf(x = i+1, y = j)
    //
    // So in Halide coordinates (x == i, y == j):
    //   rhs_col(x,y) = -d * U(x-1, y) + (1+2d) * U(x, y) - f * U(x+1, y)
    //
    // Row sweep:
    //   num_row(i,j) = -a * v[i-1][j]
    //                  + (1 + 2*a) * v[i][j]
    //                  - c * v[i+1][j]
    //
    // Mapping for v is identical: v[i][j] -> v_buf(j, i).
    // For fixed (i,j), we have:
    //   v[i-1][j] == v_buf(j, i-1) == V(x = j, y = i-1)
    //   v[i][j]   == v_buf(j, i)   == V(x = j, y = i)
    //   v[i+1][j] == v_buf(j, i+1) == V(x = j, y = i+1)
    //
    // So in Halide coordinates (x == j, y == i):
    //   rhs_row(x,y) = -a * V(x, y-1) + (1+2a) * V(x, y) - c * V(x, y+1)
    //
    // Both rhs_col and rhs_row are defined only on the interior
    // domain 1 <= x <= n-2, 1 <= y <= n-2 where those accesses are
    // within bounds. We allocate Buffers with min == 1 accordingly.
    // ------------------------------------------------------------------

    Var hx("hx"), hy("hy");

    // Column-sweep stencil: depends on u, d, f
    ImageParam U_im(type_of<num_t>(), 2, "U_im");
    Param<num_t> d_param("d_param"), f_param("f_param");
    Func rhs_col("rhs_col");

    {
        Expr one_h = cast<num_t>(1);
        Expr two_h = cast<num_t>(2);
        Expr one_plus_2d_h = one_h + two_h * d_param;

        rhs_col(hx, hy) =
            (-d_param) * U_im(hx - 1, hy) +
            one_plus_2d_h * U_im(hx, hy) -
            f_param * U_im(hx + 1, hy);
    }

    // Row-sweep stencil: depends on v, a, c
    ImageParam V_im(type_of<num_t>(), 2, "V_im");
    Param<num_t> a_param("a_param"), c_param("c_param");
    Func rhs_row("rhs_row");

    {
        Expr one_h = cast<num_t>(1);
        Expr two_h = cast<num_t>(2);
        Expr one_plus_2a_h = one_h + two_h * a_param;

        rhs_row(hx, hy) =
            (-a_param) * V_im(hx, hy - 1) +
            one_plus_2a_h * V_im(hx, hy) -
            c_param * V_im(hx, hy + 1);
    }

    // Schedules for the Halide stencil pipelines:
    // - Compute them at root (once per call to realize()).
    // - Parallelize across the slower dimension (hy, which corresponds
    //   to j in the original C code) and vectorize across hx.
    Target target = get_jit_target_from_environment();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) {
        vec_width = std::is_same<num_t, float>::value ? 8 : 4;
    }

    rhs_col.compute_root()
           .vectorize(hx, vec_width)
           .parallel(hy);
    rhs_row.compute_root()
           .vectorize(hx, vec_width)
           .parallel(hy);

    // JIT-compile these stencil pipelines once.
    rhs_col.compile_jit(target);
    rhs_row.compile_jit(target);

    // Scratch buffers for rhs_col and rhs_row. They store only the
    // interior points 1..n-2 in both dimensions.
    Buffer<num_t, 2> rhs_col_buf(n - 2, n - 2);
    rhs_col_buf.set_min(1, 1);
    Buffer<num_t, 2> rhs_row_buf(n - 2, n - 2);
    rhs_row_buf.set_min(1, 1);

    // ------------------------------------------------------------------
    // Time-stepping loop (unchanged in structure, but with:
    //   - parallelism along the i dimension,
    //   - use of Halide-precomputed numerators for q in both sweeps,
    //   - minor arithmetic hoisting.
    // ------------------------------------------------------------------
    for (int t = 1; t <= tsteps; t++) {

        // ==============================================================
        // Column sweep
        // ==============================================================
        // Precompute rhs_col(i,j) for the current u.
        U_im.set(u);
        d_param.set(d);
        f_param.set(f);
        rhs_col.realize(rhs_col_buf);

        // Forward / backward solves along j for each i.
        // Lines (fixed-i) are independent: parallelize across i.
        // NOTE: OpenMP pragmas are ignored unless compiled with -fopenmp.
        #ifdef _OPENMP
        #pragma omp parallel for schedule(static)
        #endif
        for (int i = 1; i < n - 1; i++) {
            // Boundary conditions:
            // v[0][i] = 1.0;   -> v(i, 0)
            // p[i][0] = 0.0;   -> p(0, i)
            // q[i][0] = v[0][i]; -> q(0, i)
            v(i, 0) = one;
            p(0, i) = num_t(0.0);
            q(0, i) = v(i, 0);

            // Forward sweep along j
            for (int j = 1; j < n - 1; j++) {
                // denom = a * p[i][j-1] + b;
                num_t denom = a * p(j - 1, i) + b;

                // p[i][j] = -c / denom;
                p(j, i) = -c / denom;

                // q[i][j] =
                //   (num_col(i,j) - a * q[i][j-1]) / denom;
                //
                // num_col(i,j) was precomputed as rhs_col(i,j).
                num_t num = rhs_col_buf(i, j) - a * q(j - 1, i);

                q(j, i) = num / denom;
            }

            // v[n-1][i] = 1.0; -> v(i, n-1)
            v(i, n - 1) = one;

            // Back substitution along j (descending)
            for (int j = n - 2; j >= 1; j--) {
                // v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
                v(i, j) = p(j, i) * v(i, j + 1) + q(j, i);
            }
        }

        // ==============================================================
        // Row sweep
        // ==============================================================
        // Precompute rhs_row(j,i) for the current v.
        // (Recall rhs_row(x,y) is defined with x == j, y == i.)
        V_im.set(v);
        a_param.set(a);
        c_param.set(c);
        rhs_row.realize(rhs_row_buf);

        // Again, each line (fixed i) is independent: parallelize across i.
        #ifdef _OPENMP
        #pragma omp parallel for schedule(static)
        #endif
        for (int i = 1; i < n - 1; i++) {
            // Boundary conditions:
            // u[i][0] = 1.0;   -> u(0, i)
            // p[i][0] = 0.0;   -> p(0, i)
            // q[i][0] = u[i][0]; -> q(0, i)
            u(0, i) = one;
            p(0, i) = num_t(0.0);
            q(0, i) = u(0, i);

            // Forward sweep along j
            for (int j = 1; j < n - 1; j++) {
                // denom = d * p[i][j-1] + e;
                num_t denom = d * p(j - 1, i) + e;

                // p[i][j] = -f / denom;
                p(j, i) = -f / denom;

                // q[i][j] =
                //   (num_row(i,j) - d * q[i][j-1]) / denom;
                //
                // num_row(i,j) is stored at rhs_row(j,i) because
                // rhs_row's x coordinate corresponds to j, and y to i.
                num_t num = rhs_row_buf(j, i) - d * q(j - 1, i);

                q(j, i) = num / denom;
            }

            // u[i][n-1] = 1.0; -> u(n-1, i)
            u(n - 1, i) = one;

            // Back substitution along j (descending)
            for (int j = n - 2; j >= 1; j--) {
                // u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
                u(j, i) = p(j, i) * u(j + 1, i) + q(j, i);
            }
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate Buffers.
    // C array A[i][j] is mapped as Buffer A(j, i) with shape (n, n).
    Halide::Buffer<num_t, 2> u(n, n);
    Halide::Buffer<num_t, 2> v(n, n);
    Halide::Buffer<num_t, 2> p(n, n);
    Halide::Buffer<num_t, 2> q(n, n);

    // Initialize u; v, p, q are scratch arrays.
    init_array(n, u);

    // Time only the kernel.
    auto start = std::chrono::high_resolution_clock::now();

    kernel_adi(tsteps, n, u, v, p, q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result (u) to stderr, in row-major order.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // u[i][j] == u_buf(j, i)
                std::cerr << u(j, i) << '\n';
            }
        }
    }

    // Print timing (seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
