```c++
#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>  // for std::string_literals

#include "Halide.h"

// Common PolyBench-style definitions (DATA_TYPE, etc.)
#include "defines.hpp"

// Benchmark-specific definitions (N, TSTEPS, etc.)
#include "adi.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/*
 * Initialize array u:
 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       u[i][j] = (DATA_TYPE)(i + n - j) / n;
 *
 * C array u[i][j] is mapped to Halide Buffer u(j, i).
 *
 * This version uses a small Halide pipeline with an explicit schedule:
 *  - x (the j-dimension) is vectorized for SIMD.
 *  - y (the i-dimension) is parallelized across cores.
 */
static void init_array(int n, Halide::Buffer<num_t, 2> &u) {
    Var x("x"), y("y"); // x == j (fast), y == i (slow)
    Func init_u("init_u");

    // Build the pure Halide definition:
    // u[i][j] = (i + n - j) / n  ==>  u(j, i) = ...
    Expr n_expr = cast<num_t>(n);
    init_u(x, y) = (cast<num_t>(y + n - x)) / n_expr;

    // Schedule:
    // Use the natural vector width for the current host and datatype.
    const int vec_width = Halide::natural_vector_size(type_of<num_t>());

    // Compute at root, parallelize across rows (y), and vectorize across columns (x).
    init_u
        .compute_root()
        .parallel(y)
        .vectorize(x, vec_width);

    // Realize directly into the provided buffer.
    init_u.realize(u);
}

/*
 * Main computational kernel translated to C++ operating on Halide::Buffer.
 *
 * Original signature:
 *
 *   void kernel_adi(int tsteps, int n,
 *                   DATA_TYPE u[N][N],
 *                   DATA_TYPE v[N][N],
 *                   DATA_TYPE p[N][N],
 *                   DATA_TYPE q[N][N]);
 *
 * Mapping of C indices A[i][j] -> Buffer A(j, i).
 *
 * NOTE:
 * -----
 * The ADI scheme uses tridiagonal solves with strong loop-carried
 * dependencies along one dimension (the Thomas algorithm). These
 * recurrences cannot be expressed as a legal single Halide Func
 * update (see the Halide reduction rules in tutorial lesson 9), so
 * we keep the recurrence in explicit C++ loops, but:
 *   - We aggressively hoist loop-invariant computations.
 *   - We combine divisions to share one reciprocal per iteration.
 *   - We use raw pointer + stride arithmetic to minimize Buffer
 *     index overhead and improve data locality.
 *   - The outer time-stepping and sweeps preserve the original
 *     numerical scheme exactly.
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> &u,
                       Halide::Buffer<num_t, 2> &v,
                       Halide::Buffer<num_t, 2> &p,
                       Halide::Buffer<num_t, 2> &q) {
    // ------------------------------------------------------------------
    // Scalar parameters (identical to the original code, but computed
    // once and reused).
    // ------------------------------------------------------------------
    const num_t DX   = num_t(1.0) / num_t(n);
    const num_t DY   = num_t(1.0) / num_t(n);
    const num_t DT   = num_t(1.0) / num_t(tsteps);
    const num_t B1   = num_t(2.0);
    const num_t B2   = num_t(1.0);
    const num_t mul1 = B1 * DT / (DX * DX);
    const num_t mul2 = B2 * DT / (DY * DY);

    const num_t a = -mul1 / num_t(2.0);
    const num_t b = num_t(1.0) + mul1;
    const num_t c = a;
    const num_t d = -mul2 / num_t(2.0);
    const num_t e = num_t(1.0) + mul2;
    const num_t f = d;

    const num_t one = num_t(1.0);
    const num_t zero = num_t(0.0);
    const num_t two = num_t(2.0);

    // These combinations appear in the inner loops; hoist them once.
    const num_t one_plus_two_d = one + two * d;
    const num_t one_plus_two_a = one + two * a;

    const int n_minus_1   = n - 1;
    const int n_inner_end = n - 1; // used as exclusive upper bound in < loops
    const int j_last      = n - 2; // last interior index

    // ------------------------------------------------------------------
    // Cache buffer base pointers and strides to avoid repeated virtual
    // calls / bounds metadata access in the innermost loops.
    // Layout: elem(x, y) == data[x * s0 + y * s1]
    // ------------------------------------------------------------------
    num_t *const u_data = u.data();
    num_t *const v_data = v.data();
    num_t *const p_data = p.data();
    num_t *const q_data = q.data();

    const int u_s0 = u.stride(0), u_s1 = u.stride(1);
    const int v_s0 = v.stride(0), v_s1 = v.stride(1);
    const int p_s0 = p.stride(0), p_s1 = p.stride(1);
    const int q_s0 = q.stride(0), q_s1 = q.stride(1);

    // Small inline accessors (lambda) that compile down to simple
    // pointer arithmetic. We keep the same index order as the
    // original Buffer accesses, so semantics are unchanged.
    auto U = [&](int x, int y) -> num_t & {
        return u_data[(int64_t)x * u_s0 + (int64_t)y * u_s1];
    };
    auto V = [&](int x, int y) -> num_t & {
        return v_data[(int64_t)x * v_s0 + (int64_t)y * v_s1];
    };
    auto P = [&](int x, int y) -> num_t & {
        return p_data[(int64_t)x * p_s0 + (int64_t)y * p_s1];
    };
    auto Q = [&](int x, int y) -> num_t & {
        return q_data[(int64_t)x * q_s0 + (int64_t)y * q_s1];
    };

    // ------------------------------------------------------------------
    // Time-stepping loop
    // ------------------------------------------------------------------
    for (int t = 1; t <= tsteps; ++t) {

        // ==============================================================
        // Column sweep
        // ==============================================================
        for (int i = 1; i < n_minus_1; ++i) {
            // Boundary conditions along the "column" at fixed i.
            // v[0][i] = 1.0;   -> V(i, 0)
            V(i, 0) = one;

            // p[i][0] = 0.0;   -> P(0, i)
            P(0, i) = zero;

            // q[i][0] = v[0][i]; -> Q(0, i)
            Q(0, i) = V(i, 0);

            // ----------------------------------------------------------
            // Forward sweep along j: Thomas algorithm coefficients.
            // j = 1 .. n-2
            // ----------------------------------------------------------
            for (int j = 1; j < j_last; ++j) {
                const num_t p_prev = P(j - 1, i);
                const num_t q_prev = Q(j - 1, i);

                const num_t denom = a * p_prev + b;
                // Share one reciprocal for both p and q updates to
                // reduce division cost.
                const num_t inv_denom = one / denom;

                // p[i][j] = -c / (a * p[i][j-1] + b);
                P(j, i) = (-c) * inv_denom;

                // q[i][j] =
                //   (-d * u[j][i-1]
                //    + (1 + 2*d) * u[j][i]
                //    - f * u[j][i+1]
                //    - a * q[i][j-1]) /
                //   (a * p[i][j-1] + b);
                const num_t u_im1 = U(i - 1, j);
                const num_t u_i   = U(i,     j);
                const num_t u_ip1 = U(i + 1, j);

                const num_t num = -d * u_im1
                                  + one_plus_two_d * u_i
                                  - f * u_ip1
                                  - a * q_prev;

                Q(j, i) = num * inv_denom;
            }

            // v[n-1][i] = 1.0; -> V(i, n-1)
            V(i, n_minus_1) = one;

            // ----------------------------------------------------------
            // Back substitution along j (descending).
            // j = n-2 .. 1
            // ----------------------------------------------------------
            for (int j = j_last; j >= 1; --j) {
                // v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
                V(i, j) = P(j, i) * V(i, j + 1) + Q(j, i);
            }
        }

        // ==============================================================
        // Row sweep
        // ==============================================================
        for (int i = 1; i < n_minus_1; ++i) {
            // u[i][0] = 1.0; -> U(0, i)
            U(0, i) = one;

            // p[i][0] = 0.0; -> P(0, i)
            P(0, i) = zero;

            // q[i][0] = u[i][0]; -> Q(0, i)
            Q(0, i) = U(0, i);

            // ----------------------------------------------------------
            // Forward sweep along j
            // j = 1 .. n-2
            // ----------------------------------------------------------
            for (int j = 1; j < j_last; ++j) {
                const num_t p_prev = P(j - 1, i);
                const num_t q_prev = Q(j - 1, i);

                const num_t denom = d * p_prev + e;
                const num_t inv_denom = one / denom;

                // p[i][j] = -f / (d * p[i][j-1] + e);
                P(j, i) = (-f) * inv_denom;

                // q[i][j] =
                //   (-a * v[i-1][j]
                //    + (1 + 2*a) * v[i][j]
                //    - c * v[i+1][j]
                //    - d * q[i][j-1]) /
                //   (d * p[i][j-1] + e);
                const num_t v_im1 = V(j, i - 1);
                const num_t v_i   = V(j, i);
                const num_t v_ip1 = V(j, i + 1);

                const num_t num = -a * v_im1
                                  + one_plus_two_a * v_i
                                  - c * v_ip1
                                  - d * q_prev;

                Q(j, i) = num * inv_denom;
            }

            // u[i][n-1] = 1.0; -> U(n-1, i)
            U(n_minus_1, i) = one;

            // ----------------------------------------------------------
            // Back substitution along j (descending).
            // j = n-2 .. 1
            // ----------------------------------------------------------
            for (int j = j_last; j >= 1; --j) {
                // u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
                U(j, i) = P(j, i) * U(j + 1, i) + Q(j, i);
            }
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate Buffers.
    // C array A[i][j] is mapped as Buffer A(j, i) with shape (n, n).
    Halide::Buffer<num_t, 2> u(n, n);
    Halide::Buffer<num_t, 2> v(n, n);
    Halide::Buffer<num_t, 2> p(n, n);
    Halide::Buffer<num_t, 2> q(n, n);

    // Initialize u; v, p, q are scratch arrays.
    init_array(n, u);

    // Time only the kernel.
    auto start = std::chrono::high_resolution_clock::now();

    kernel_adi(tsteps, n, u, v, p, q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result (u) to stderr, in row-major order.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // u[i][j] == u_buf(j, i)
                std::cerr << u(j, i) << '\n';
            }
        }
    }

    // Print timing (seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
