```c++
#include <chrono>
#include <iomanip>
#include <iostream>
#include <thread>
#include <vector>
#include <algorithm>

#include "Halide.h"

// Common PolyBench-style definitions (DATA_TYPE, etc.)
#include "defines.hpp"

// Benchmark-specific definitions (N, TSTEPS, etc.)
#include "adi.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/*
 * Initialize array u:
 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       u[i][j] = (DATA_TYPE)(i + n - j) / n;
 *
 * C array u[i][j] is mapped to Halide Buffer u(j, i).
 */
static void init_array(int n, Halide::Buffer<num_t, 2> u) {
    // x == j (fast), y == i (slow)
    Var x("x"), y("y");
    Func init_u("init_u");

    // u[i][j] = (i + n - j) / n  ==>  u(j, i) = ...
    init_u(x, y) = cast<num_t>(y + n - x) / cast<num_t>(n);

    // Simple but effective schedule: vectorize across x (columns), parallelize across y (rows).
    // A fixed small vector width (4) is a reasonable compromise for both float and double.
    init_u
        .vectorize(x, 4)
        .parallel(y);

    init_u.realize(u);
}

/*
 * A small helper: run a 1D range [begin, end) in parallel chunks.
 * The worker functor takes (int i_begin, int i_end) and processes [i_begin, i_end).
 *
 * This is used to distribute the independent tridiagonal solves for different
 * columns/rows across hardware threads. Each column/row is still processed
 * sequentially along j, preserving the original numerical scheme.
 */
template <class F>
static void parallel_for_1d(int begin, int end, F &&func) {
    const int total = end - begin;
    if (total <= 0) {
        return;
    }

    unsigned int hw = std::thread::hardware_concurrency();
    int max_threads = hw ? static_cast<int>(hw) : 1;
    // Do not spawn more threads than there is work.
    int num_threads = std::min(max_threads, total);

    if (num_threads <= 1) {
        func(begin, end);
        return;
    }

    const int chunk = (total + num_threads - 1) / num_threads;
    std::vector<std::thread> threads;
    threads.reserve(num_threads);

    int i_begin = begin;
    while (i_begin < end) {
        int i_end = std::min(i_begin + chunk, end);
        threads.emplace_back([=, &func]() {
            func(i_begin, i_end);
        });
        i_begin = i_end;
    }

    for (auto &t : threads) {
        t.join();
    }
}

/*
 * Main computational kernel translated to C++ operating on Halide::Buffer.
 *
 * Original signature:
 *
 *   void kernel_adi(int tsteps, int n,
 *                   DATA_TYPE u[N][N],
 *                   DATA_TYPE v[N][N],
 *                   DATA_TYPE p[N][N],
 *                   DATA_TYPE q[N][N]);
 *
 * Mapping of C indices A[i][j] -> Buffer A(j, i).
 *
 * This implementation preserves the original numerical scheme, but:
 *   - Hoists constant coefficients out of the time loop.
 *   - Precomputes the tridiagonal coefficient sequences p and their
 *     denominators once (they are identical for all rows/columns and timesteps).
 *   - Improves data locality by keeping the original i (row) outer / j (col)
 *     inner order, which matches the Buffer layout (x = j is the fast axis).
 *   - Parallelizes the independent tridiagonal solves across i using
 *     std::thread, leaving the j recurrences sequential inside each thread.
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> u,
                       Halide::Buffer<num_t, 2> v,
                       Halide::Buffer<num_t, 2> p,
                       Halide::Buffer<num_t, 2> q) {
    if (tsteps <= 0 || n <= 2) {
        return; // nothing to do or degenerate domain
    }

    // -------------------------------------------------------------------------
    // Scalar parameters (constants over all timesteps)
    // -------------------------------------------------------------------------
    const num_t one  = num_t(1.0);
    const num_t zero = num_t(0.0);

    const num_t DX   = one / num_t(n);
    const num_t DY   = one / num_t(n);
    const num_t DT   = one / num_t(tsteps);
    const num_t B1   = num_t(2.0);
    const num_t B2   = num_t(1.0);
    const num_t mul1 = B1 * DT / (DX * DX);
    const num_t mul2 = B2 * DT / (DY * DY);

    const num_t a = -mul1 / num_t(2.0);
    const num_t b = one + mul1;
    const num_t c = a;
    const num_t d = -mul2 / num_t(2.0);
    const num_t e = one + mul2;
    const num_t f = d;

    // Precompute coefficients used repeatedly inside the sweeps.
    const num_t one_plus_2d = one + num_t(2.0) * d;
    const num_t one_plus_2a = one + num_t(2.0) * a;

    // -------------------------------------------------------------------------
    // Precompute tridiagonal coefficients p and denominators along j.
    //
    // In both the column and row sweeps, the forward sweep recurrence
    // for p[i][j] has the same form for all i and all timesteps:
    //
    //   Column sweep:
    //     p[i][0] = 0
    //     p[i][j] = -c / (a * p[i][j-1] + b)
    //
    //   Row sweep:
    //     p[i][0] = 0
    //     p[i][j] = -f / (d * p[i][j-1] + e)
    //
    // The recurrence depends only on constants (a,b,c) or (d,e,f) and
    // on p[i][j-1], so for fixed (a,b,c) it produces the same sequence
    // along j for every i and timestep. We can therefore precompute
    // these 1D sequences once and reuse them in every sweep.
    //
    // We also precompute the denominators (a * p[j-1] + b) and
    // (d * p[j-1] + e) so that inside the time-stepping loops we
    // only perform a multiply/add for the right-hand side and one
    // division using the cached denominator.
    //
    // Note: We still set p(0, i) inside the sweeps for compatibility
    // with any external inspection of p, but the interior p(j, i)
    // values are no longer needed for correctness of u or v and are
    // not stored back to the 2D buffer.
    // -------------------------------------------------------------------------
    const int inner_low  = 1;
    const int inner_high = n - 1; // exclusive upper bound for i and j loops
    const int inner_len  = inner_high - inner_low; // == n - 2

    std::vector<num_t> p_col(n, zero);     // p sequence for column sweep (j dimension)
    std::vector<num_t> denom_col(n, zero); // denominators for column sweep
    std::vector<num_t> p_row(n, zero);     // p sequence for row sweep (j dimension)
    std::vector<num_t> denom_row(n, zero); // denominators for row sweep

    // Base case j == 0 for both sweeps.
    p_col[0] = zero;
    p_row[0] = zero;

    for (int j = 1; j < n - 1; ++j) {
        // Column sweep coefficients.
        num_t denom_c = a * p_col[j - 1] + b;
        denom_col[j]  = denom_c;
        p_col[j]      = -c / denom_c;

        // Row sweep coefficients.
        num_t denom_r = d * p_row[j - 1] + e;
        denom_row[j]  = denom_r;
        p_row[j]      = -f / denom_r;
    }

    // -------------------------------------------------------------------------
    // Time-stepping loop
    // -------------------------------------------------------------------------
    for (int t = 1; t <= tsteps; t++) {

        // ---------------------------------------------------------------------
        // Column sweep
        //
        // For each i (1..n-2), we independently solve a tridiagonal system
        // along j (1..n-2) for v and q using the Thomas algorithm. The
        // different i-values are independent, so we parallelize over i.
        // ---------------------------------------------------------------------
        parallel_for_1d(inner_low, inner_high, [&](int i_begin, int i_end) {
            for (int i = i_begin; i < i_end; ++i) {
                // v[0][i] = 1.0;
                v(i, 0) = one;

                // p[i][0] = 0.0;  (not used in computation, but we keep it for consistency)
                p(0, i) = zero;

                // q[i][0] = v[0][i];
                q(0, i) = v(i, 0);

                // Forward sweep along j: compute q[i][j] using precomputed denominators.
                for (int j = 1; j < n - 1; ++j) {
                    const num_t denom = denom_col[j];

                    // q[i][j] =
                    //   (-d * u[j][i-1]
                    //    + (1 + 2*d) * u[j][i]
                    //    - f * u[j][i+1]
                    //    - a * q[i][j-1]) /
                    //   (a * p[i][j-1] + b);
                    //
                    // Mapping C u[j][i] -> Buffer u(i, j) becomes u(i, j) in code,
                    // but recall Buffer(j, i) = C u[i][j] so we must use u(i, j)
                    // consistently with the original mapping (already done in the
                    // starting version of this code).
                    //
                    // Here: u(j, i-1) == u[i-1][j], etc.
                    const num_t num =
                        -d * u(i - 1, j) +
                        one_plus_2d * u(i, j) -
                        f * u(i + 1, j) -
                        a * q(j - 1, i);

                    q(j, i) = num / denom;
                }

                // v[n-1][i] = 1.0;
                v(i, n - 1) = one;

                // Back substitution along j (descending):
                //   v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
                // We use the precomputed p_col[j] sequence instead of p(j, i).
                for (int j = n - 2; j >= 1; --j) {
                    v(i, j) = p_col[j] * v(i, j + 1) + q(j, i);
                }
            }
        });

        // ---------------------------------------------------------------------
        // Row sweep
        //
        // Now we solve, independently for each i (1..n-2), a tridiagonal
        // system along j (1..n-2) for u and q, using v as input. Again,
        // the different values of i are independent, so we parallelize
        // over i and keep the Thomas algorithm sequential along j.
        // ---------------------------------------------------------------------
        parallel_for_1d(inner_low, inner_high, [&](int i_begin, int i_end) {
            for (int i = i_begin; i < i_end; ++i) {
                // u[i][0] = 1.0;
                u(0, i) = one;

                // p[i][0] = 0.0;  (again, for consistency only)
                p(0, i) = zero;

                // q[i][0] = u[i][0];
                q(0, i) = u(0, i);

                // Forward sweep along j:
                //   p[i][j] = -f / (d * p[i][j-1] + e);
                //   q[i][j] =
                //     (-a * v[i-1][j]
                //      + (1 + 2*a) * v[i][j]
                //      - c * v[i+1][j]
                //      - d * q[i][j-1]) /
                //     (d * p[i][j-1] + e);
                //
                // We reuse the precomputed denominators denom_row[j] here.
                for (int j = 1; j < n - 1; ++j) {
                    const num_t denom = denom_row[j];

                    const num_t num =
                        -a * v(j, i - 1) +
                        one_plus_2a * v(j, i) -
                        c * v(j, i + 1) -
                        d * q(j - 1, i);

                    q(j, i) = num / denom;
                }

                // u[i][n-1] = 1.0;
                u(n - 1, i) = one;

                // Back substitution along j (descending):
                //   u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
                // Use precomputed p_row[j] instead of p(j, i).
                for (int j = n - 2; j >= 1; --j) {
                    u(j, i) = p_row[j] * u(j + 1, i) + q(j, i);
                }
            }
        });
    }
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate Buffers.
    // C array A[i][j] is mapped as Buffer A(j, i) with shape (n, n).
    Halide::Buffer<num_t, 2> u(n, n);
    Halide::Buffer<num_t, 2> v(n, n);
    Halide::Buffer<num_t, 2> p(n, n);
    Halide::Buffer<num_t, 2> q(n, n);

    // Initialize u; v, p, q are scratch arrays.
    init_array(n, u);

    // Time only the kernel.
    auto start = std::chrono::high_resolution_clock::now();

    kernel_adi(tsteps, n, u, v, p, q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result (u) to stderr, in row-major order.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // C u[i][j] == Buffer u(j, i)
                std::cerr << u(j, i) << '\n';
            }
        }
    }

    // Print timing (seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
