```cpp
#include <algorithm>
#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>
#include <thread>
#include <vector>

#include "Halide.h"

// Common PolyBench-style definitions (DATA_TYPE, etc.)
#include "defines.hpp"

// Benchmark-specific definitions (N, TSTEPS, etc.)
#include "adi.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/*
 * Simple 1D parallel_for helper using std::thread.
 *
 * - Executes func(i) for i in [begin, end) in parallel.
 * - Uses up to hardware_concurrency() threads, but never more threads
 *   than loop iterations.
 * - For very small ranges (<=1), runs serially to avoid thread overhead.
 *
 * We use this to parallelize over the outer spatial index i in the ADI
 * sweeps; each i processes a distinct column/row and is independent,
 * so this is thread-safe.
 */
template <typename F>
inline void parallel_for_1d(int begin, int end, const F &func) {
    const int total = end - begin;
    if (total <= 0) {
        return;
    }

    unsigned hw = std::thread::hardware_concurrency();
    int num_threads = hw ? static_cast<int>(hw) : 1;
    num_threads = std::min(num_threads, total);

    if (num_threads <= 1) {
        // Serial fallback.
        for (int i = begin; i < end; ++i) {
            func(i);
        }
        return;
    }

    const int chunk = (total + num_threads - 1) / num_threads;

    std::vector<std::thread> threads;
    threads.reserve(num_threads);

    for (int t = 0; t < num_threads; ++t) {
        const int start = begin + t * chunk;
        const int stop  = std::min(start + chunk, end);
        if (start >= stop) break;

        threads.emplace_back([&func, start, stop]() {
            for (int i = start; i < stop; ++i) {
                func(i);
            }
        });
    }

    for (auto &th : threads) {
        th.join();
    }
}

/*
 * Initialize array u:
 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       u[i][j] = (DATA_TYPE)(i + n - j) / n;
 *
 * C array u[i][j] is mapped to Halide Buffer u(j, i).
 *
 * Here we express initialization as a Halide pipeline and
 * apply a simple schedule (vectorize + parallelize) to exploit
 * SIMD and multiple cores.
 */
static void init_array(int n, Halide::Buffer<num_t, 2> u) {
    Var x("x"), y("y"); // x == j (fast), y == i (slow)
    Func init_u("init_u");

    // u[i][j] = (i + n - j) / n  ==>  u(j, i) = ...
    Expr n_expr = cast<num_t>(n);
    init_u(x, y) = (cast<num_t>(y) + n_expr - cast<num_t>(x)) / n_expr;

    // Basic schedule: vectorize across x (fast dimension), parallelize across y.
    Target target = get_host_target();
    int vec_width = natural_vector_size<num_t>(target);
    if (vec_width < 1) vec_width = 1;
    vec_width = std::min(vec_width, n); // avoid over-vectorizing very small problems

    init_u
        .vectorize(x, vec_width)
        .parallel(y);

    init_u.realize(u);
}

/*
 * Main computational kernel translated to C++ operating on Halide::Buffer.
 *
 * Original signature:
 *
 *   void kernel_adi(int tsteps, int n,
 *                   DATA_TYPE u[N][N],
 *                   DATA_TYPE v[N][N],
 *                   DATA_TYPE p[N][N],
 *                   DATA_TYPE q[N][N]);
 *
 * Mapping of C indices A[i][j] -> Buffer A(j, i).
 *
 * NOTE ABOUT HALIDE USAGE:
 * ------------------------
 * The ADI kernel is fundamentally a collection of tridiagonal solves
 * (Thomas algorithm) along 1D lines, which are inherently sequential in
 * the "j" dimension (each element depends on the previous). Halide's
 * pure functional update model does not directly support such
 * loop-carried dependencies as legal self-referential updates.
 *
 * In accordance with the provided optimization guidelines, we therefore:
 *   - Keep the dynamic-programming style recurrences in host code.
 *   - Use Halide::Buffer to manage all data.
 *   - Improve locality and efficiency by:
 *       * Using contiguous row pointers instead of Buffer(i,j) calls.
 *       * Hoisting invariant computations.
 *       * Keeping the forward-sweep and back-substitution state in
 *         registers (scalars) instead of repeatedly loading from memory.
 *       * Parallelizing the outer i-loops with a thread pool.
 *
 * This preserves the original numerical algorithm exactly (same
 * operation order along each 1D line), while making the memory
 * access patterns and parallel execution more efficient.
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> u,
                       Halide::Buffer<num_t, 2> v,
                       Halide::Buffer<num_t, 2> p,
                       Halide::Buffer<num_t, 2> q) {
    // ------------------------------------------------------------------
    // Precompute scalar coefficients (time/space steps and ADI factors).
    // ------------------------------------------------------------------
    const num_t one = num_t(1.0);
    const num_t two = num_t(2.0);

    const num_t DX   = one / num_t(n);
    const num_t DY   = one / num_t(n);
    const num_t DT   = one / num_t(tsteps);
    const num_t B1   = num_t(2.0);
    const num_t B2   = num_t(1.0);
    const num_t mul1 = B1 * DT / (DX * DX);
    const num_t mul2 = B2 * DT / (DY * DY);

    const num_t a = -mul1 / num_t(2.0);
    const num_t b = one + mul1;
    const num_t c = a;
    const num_t d = -mul2 / num_t(2.0);
    const num_t e = one + mul2;
    const num_t f = d;

    // Frequently used combinations.
    const num_t one_plus_2d = one + two * d;
    const num_t one_plus_2a = one + two * a;

    // ------------------------------------------------------------------
    // Raw pointers and strides for faster indexed access.
    // Buffer is created as Buffer(n, n) so we expect a simple
    // row-major-like layout: stride(0) == 1, stride(1) == n.
    // (Assertions are for debug; compiled out in NDEBUG builds.)
    // ------------------------------------------------------------------
    const int stride_x_u = u.stride(0);
    const int stride_y_u = u.stride(1);
    const int stride_x_v = v.stride(0);
    const int stride_y_v = v.stride(1);
    const int stride_x_p = p.stride(0);
    const int stride_y_p = p.stride(1);
    const int stride_x_q = q.stride(0);
    const int stride_y_q = q.stride(1);

#ifndef NDEBUG
    // For freshly-constructed Buffers this should hold.
    assert(stride_x_u == 1 && stride_y_u == n);
    assert(stride_x_v == 1 && stride_y_v == n);
    assert(stride_x_p == 1 && stride_y_p == n);
    assert(stride_x_q == 1 && stride_y_q == n);
#endif

    num_t *const u_data = u.data();
    num_t *const v_data = v.data();
    num_t *const p_data = p.data();
    num_t *const q_data = q.data();

    // ------------------------------------------------------------------
    // Time-stepping loop.
    // We keep this outermost loop serial, but parallelize over the
    // spatial index i inside each sweep.
    // ------------------------------------------------------------------
    for (int t = 1; t <= tsteps; ++t) {

        // ==============================================================
        // Column sweep: for each (C) i, solve along j.
        //
        // Original C (conceptual):
        //   for (i = 1; i < n-1; i++) {
        //     v[0][i] = 1.0;
        //     p[i][0] = 0.0;
        //     q[i][0] = v[0][i];
        //     forward j=1..n-2: compute p[i][j], q[i][j]
        //     v[n-1][i] = 1.0;
        //     backward j=n-2..1: compute v[j][i]
        //   }
        //
        // In Buffer notation A[i][j] -> A_buf(j, i):
        //   v(i, 0)    = v[0][i]
        //   p(0, i)    = p[i][0]
        //   q(0, i)    = q[i][0]
        //   p(j, i)    = p[i][j]
        //   q(j, i)    = q[i][j]
        //   v(i, j)    = v[j][i]
        //
        // We parallelize over i and keep the j-direction sequential,
        // but use:
        //   - row pointers (along x == j) for contiguous access;
        //   - scalar p_prev, q_prev for forward sweep to avoid
        //     repeatedly loading p(j-1,i), q(j-1,i) from memory;
        //   - scalar v_next for backward substitution to avoid
        //     extra loads.
        // ==============================================================
        auto column_sweep = [&](int i) {
            // Only interior i participate: i in [1, n-2].
            // Map to row pointers along x=j for fixed y=i.
            num_t *const u_im1 = u_data + (i - 1) * stride_y_u; // u(j, i-1)
            num_t *const u_i   = u_data + i * stride_y_u;       // u(j, i)
            num_t *const u_ip1 = u_data + (i + 1) * stride_y_u; // u(j, i+1)

            num_t *const v_i   = v_data + i * stride_y_v;       // v(j, i) (we'll mostly use v_i[j] with j as "row")
            num_t *const p_i   = p_data + i * stride_y_p;       // p(j, i)
            num_t *const q_i   = q_data + i * stride_y_q;       // q(j, i)

            // Boundary conditions: v[0][i] = 1; p[i][0] = 0; q[i][0] = v[0][i].
            v_i[0] = one;
            p_i[0] = num_t(0.0);
            q_i[0] = v_i[0];

            // Forward sweep along j: use scalar state for previous p,q
            // to keep them in registers and reduce memory traffic.
            num_t p_prev = p_i[0];
            num_t q_prev = q_i[0];

            for (int j = 1; j < n - 1; ++j) {
                const num_t denom  = a * p_prev + b;
                const num_t p_curr = -c / denom;

                const num_t u_jm1 = u_im1[j];
                const num_t u_j   = u_i[j];
                const num_t u_jp1 = u_ip1[j];

                const num_t rhs   = -d * u_jm1 +
                                    one_plus_2d * u_j -
                                    f * u_jp1 -
                                    a * q_prev;
                const num_t q_curr = rhs / denom;

                p_i[j] = p_curr;
                q_i[j] = q_curr;

                p_prev = p_curr;
                q_prev = q_curr;
            }

            // Boundary: v[n-1][i] = 1.0.
            v_i[n - 1] = one;

            // Back substitution along j (descending): again keep the
            // "next" v in a scalar to avoid extra loads.
            num_t v_next = v_i[n - 1];
            for (int j = n - 2; j >= 1; --j) {
                const num_t v_j = p_i[j] * v_next + q_i[j];
                v_i[j] = v_j;
                v_next = v_j;
            }
        };

        // Parallelize column sweep over i in [1, n-1) => [1, n-2].
        parallel_for_1d(1, n - 1, column_sweep);

        // ==============================================================
        // Row sweep: for each (C) i, solve along j, now updating u
        // using v as the known field.
        //
        // Original C (conceptual):
        //   for (i = 1; i < n-1; i++) {
        //     u[i][0] = 1.0;
        //     p[i][0] = 0.0;
        //     q[i][0] = u[i][0];
        //     forward j=1..n-2: compute p[i][j], q[i][j]
        //       using v[i-1][j], v[i][j], v[i+1][j]
        //     u[i][n-1] = 1.0;
        //     backward j=n-2..1: compute u[i][j]
        //   }
        //
        // In Buffer notation:
        //   u(0, i)      = u[i][0]
        //   u(n-1, i)    = u[i][n-1]
        //   p(j, i), q(j, i) as before.
        //
        // We again parallelize over i and keep the j-direction
        // sequential, using row pointers and scalar state.
        // ==============================================================
        auto row_sweep = [&](int i) {
            num_t *const u_i   = u_data + i * stride_y_u;       // u(j, i)
            num_t *const p_i   = p_data + i * stride_y_p;       // p(j, i)
            num_t *const q_i   = q_data + i * stride_y_q;       // q(j, i)

            num_t *const v_im1 = v_data + (i - 1) * stride_y_v; // v(j, i-1)
            num_t *const v_i   = v_data + i * stride_y_v;       // v(j, i)
            num_t *const v_ip1 = v_data + (i + 1) * stride_y_v; // v(j, i+1)

            // Boundary conditions: u[i][0] = 1; p[i][0] = 0; q[i][0] = u[i][0].
            u_i[0] = one;
            p_i[0] = num_t(0.0);
            q_i[0] = u_i[0];

            num_t p_prev = p_i[0];
            num_t q_prev = q_i[0];

            // Forward sweep along j.
            for (int j = 1; j < n - 1; ++j) {
                const num_t denom  = d * p_prev + e;
                const num_t p_curr = -f / denom;

                const num_t v_jm1 = v_im1[j];
                const num_t v_j   = v_i[j];
                const num_t v_jp1 = v_ip1[j];

                const num_t rhs   = -a * v_jm1 +
                                    one_plus_2a * v_j -
                                    c * v_jp1 -
                                    d * q_prev;
                const num_t q_curr = rhs / denom;

                p_i[j] = p_curr;
                q_i[j] = q_curr;

                p_prev = p_curr;
                q_prev = q_curr;
            }

            // Boundary: u[i][n-1] = 1.0.
            u_i[n - 1] = one;

            // Back substitution along j (descending).
            num_t u_next = u_i[n - 1];
            for (int j = n - 2; j >= 1; --j) {
                const num_t u_j = p_i[j] * u_next + q_i[j];
                u_i[j] = u_j;
                u_next = u_j;
            }
        };

        // Parallelize row sweep over i in [1, n-1) => [1, n-2].
        parallel_for_1d(1, n - 1, row_sweep);
    }
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate Buffers.
    // C array A[i][j] is mapped as Buffer A(j, i) with shape (n, n).
    Halide::Buffer<num_t, 2> u(n, n);
    Halide::Buffer<num_t, 2> v(n, n);
    Halide::Buffer<num_t, 2> p(n, n);
    Halide::Buffer<num_t, 2> q(n, n);

    // Initialize u; v, p, q are scratch arrays.
    init_array(n, u);

    // Time only the kernel.
    auto start = std::chrono::high_resolution_clock::now();

    kernel_adi(tsteps, n, u, v, p, q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result (u) to stderr, in row-major order.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // u[i][j] == u_buf(j, i)
                std::cerr << u(j, i) << '\n';
            }
        }
    }

    // Print timing (seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
