```c++
#include <chrono>
#include <iomanip>
#include <iostream>
#include <thread>
#include <vector>

#include "Halide.h"

// Common PolyBench-style definitions (DATA_TYPE, etc.)
#include "defines.hpp"

// Benchmark-specific definitions (N, TSTEPS, etc.)
#include "adi.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/*
 * Simple thread-parallel for over an integer range [start, end).
 *
 * We parallelize over the outer i-dimension of the ADI sweeps, which are
 * independent for different i (each i corresponds to an independent
 * tridiagonal solve along j). This preserves the original semantics and
 * exploits all available CPU cores.
 */
template <class F>
inline void parallel_for_1d(int start, int end, F &&fn) {
    const int length = end - start;
    if (length <= 0) return;

    const unsigned hw = std::thread::hardware_concurrency();
    const int max_threads = hw > 0 ? static_cast<int>(hw) : 32;
    const int num_threads = std::min(max_threads, length);

    if (num_threads <= 1) {
        // Fallback to serial execution.
        for (int i = start; i < end; ++i) {
            fn(i);
        }
        return;
    }

    std::vector<std::thread> threads(num_threads);
    for (int t = 0; t < num_threads; ++t) {
        const int block_start = start + (length * t) / num_threads;
        const int block_end   = start + (length * (t + 1)) / num_threads;
        threads[t] = std::thread([block_start, block_end, &fn]() {
            for (int i = block_start; i < block_end; ++i) {
                fn(i);
            }
        });
    }
    for (auto &th : threads) {
        th.join();
    }
}

/*
 * Initialize array u:
 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       u[i][j] = (DATA_TYPE)(i + n - j) / n;
 *
 * C array u[i][j] is mapped to Halide Buffer u(j, i).
 *
 * We express this initialization as a Halide pipeline and add a
 * simple schedule for vectorization and parallelization.
 */
static void init_array(int n, Halide::Buffer<num_t, 2> u) {
    Var x("x"), y("y"); // x == j (fast), y == i (slow)
    Func init_u("init_u");

    // u[i][j] = (i + n - j) / n  ==>  u(j, i) = ...
    init_u(x, y) = cast<num_t>(y + n - x) / cast<num_t>(n);

    // Simple performance-oriented schedule:
    //  - vectorize along the fast x-dimension
    //  - parallelize over y (rows)
    Target target = get_host_target();
    const int vec_width = Halide::natural_vector_size<num_t>(target);

    init_u
        .vectorize(x, vec_width)
        .parallel(y);

    // JIT-compile and realize into the provided buffer.
    init_u.realize(u);
}

/*
 * Main computational kernel translated to C++ operating on Halide::Buffer.
 *
 * Original signature:
 *
 *   void kernel_adi(int tsteps, int n,
 *                   DATA_TYPE u[N][N],
 *                   DATA_TYPE v[N][N],
 *                   DATA_TYPE p[N][N],
 *                   DATA_TYPE q[N][N]);
 *
 * Mapping of C indices A[i][j] -> Buffer A(j, i).
 *
 * The core ADI algorithm consists of 1D tridiagonal solves along
 * columns and rows (Thomas algorithm). These are inherently
 * sequential along the j-dimension, so we keep the j-loops
 * sequential but parallelize across the independent i-dimension.
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> u,
                       Halide::Buffer<num_t, 2> v,
                       Halide::Buffer<num_t, 2> p,
                       Halide::Buffer<num_t, 2> q) {
    // Precompute scalar coefficients once (time-invariant).
    const num_t one = num_t(1.0);
    const num_t two = num_t(2.0);

    const num_t DX   = one / num_t(n);
    const num_t DY   = one / num_t(n);
    const num_t DT   = one / num_t(tsteps);
    const num_t B1   = num_t(2.0);
    const num_t B2   = num_t(1.0);
    const num_t mul1 = B1 * DT / (DX * DX);
    const num_t mul2 = B2 * DT / (DY * DY);

    const num_t a = -mul1 / num_t(2.0);
    const num_t b = one + mul1;
    const num_t c = a;
    const num_t d = -mul2 / num_t(2.0);
    const num_t e = one + mul2;
    const num_t f = d;

    // Useful precomputed combinations used inside the sweeps.
    const num_t center_d = one + two * d; // (1 + 2*d)
    const num_t center_a = one + two * a; // (1 + 2*a)
    const num_t neg_c    = -c;            // == -a
    const num_t neg_f    = -f;            // == -d

    // Convenience: interior range [1, n-1) for i and j loops.
    const int i_begin = 1;
    const int i_end   = n - 1;
    const int j_begin = 1;
    const int j_end   = n - 1;
    const int j_last  = n - 1;

    // Time-stepping loop (sequential).
    for (int t = 1; t <= tsteps; t++) {

        // ------------------------------------------------------------
        // Column sweep (solve along "j" for each fixed i).
        // ------------------------------------------------------------
        parallel_for_1d(i_begin, i_end, [&](int i) {
            // Boundary conditions:
            // v[0][i] = 1.0;
            v(i, 0) = one;

            // p[i][0] = 0.0;
            p(0, i) = num_t(0.0);

            // q[i][0] = v[0][i];
            q(0, i) = v(i, 0);

            // Forward sweep along j: j = 1 .. n-2
            for (int j = j_begin; j < j_end; ++j) {
                // denom = a * p[i][j-1] + b;
                const num_t p_prev = p(j - 1, i);
                const num_t denom  = a * p_prev + b;

                // p[i][j] = -c / denom;
                p(j, i) = neg_c / denom;

                // q[i][j] =
                //   (-d * u[j][i-1]
                //    + (1 + 2*d) * u[j][i]
                //    - f * u[j][i+1]
                //    - a * q[i][j-1]) /
                //   denom;
                const num_t u_im1 = u(i - 1, j);
                const num_t u_i   = u(i,     j);
                const num_t u_ip1 = u(i + 1, j);
                const num_t q_prev = q(j - 1, i);

                const num_t num =
                    (-d) * u_im1 +
                    center_d * u_i +
                    (-f) * u_ip1 -
                    a * q_prev;

                q(j, i) = num / denom;
            }

            // v[n-1][i] = 1.0;
            v(i, j_last) = one;

            // Back substitution along j (descending): j = n-2 .. 1
            for (int j = j_end - 1; j >= j_begin; --j) {
                // v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
                const num_t v_next = v(i, j + 1);
                v(i, j) = p(j, i) * v_next + q(j, i);
            }
        });

        // ------------------------------------------------------------
        // Row sweep (solve along "j" for each fixed i, using v).
        // ------------------------------------------------------------
        parallel_for_1d(i_begin, i_end, [&](int i) {
            // u[i][0] = 1.0;
            u(0, i) = one;

            // p[i][0] = 0.0;
            p(0, i) = num_t(0.0);

            // q[i][0] = u[i][0];
            q(0, i) = u(0, i);

            // Forward sweep along j: j = 1 .. n-2
            for (int j = j_begin; j < j_end; ++j) {
                // denom = d * p[i][j-1] + e;
                const num_t p_prev = p(j - 1, i);
                const num_t denom  = d * p_prev + e;

                // p[i][j] = -f / denom;
                p(j, i) = neg_f / denom;

                // q[i][j] =
                //   (-a * v[i-1][j]
                //    + (1 + 2*a) * v[i][j]
                //    - c * v[i+1][j]
                //    - d * q[i][j-1]) /
                //   denom;
                const num_t v_im1 = v(j, i - 1);
                const num_t v_i   = v(j, i);
                const num_t v_ip1 = v(j, i + 1);
                const num_t q_prev = q(j - 1, i);

                const num_t num =
                    (-a) * v_im1 +
                    center_a * v_i +
                    (-c) * v_ip1 -
                    d * q_prev;

                q(j, i) = num / denom;
            }

            // u[i][n-1] = 1.0;
            u(j_last, i) = one;

            // Back substitution along j (descending): j = n-2 .. 1
            for (int j = j_end - 1; j >= j_begin; --j) {
                // u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
                const num_t u_next = u(j + 1, i);
                u(j, i) = p(j, i) * u_next + q(j, i);
            }
        });
    }
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate Buffers.
    // C array A[i][j] is mapped as Buffer A(j, i) with shape (n, n).
    Halide::Buffer<num_t, 2> u(n, n);
    Halide::Buffer<num_t, 2> v(n, n);
    Halide::Buffer<num_t, 2> p(n, n);
    Halide::Buffer<num_t, 2> q(n, n);

    // Initialize u; v, p, q are scratch arrays.
    init_array(n, u);

    // Time only the kernel.
    auto start = std::chrono::high_resolution_clock::now();

    kernel_adi(tsteps, n, u, v, p, q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result (u) to stderr, in row-major order.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // u[i][j] == u_buf(j, i)
                std::cerr << u(j, i) << '\n';
            }
        }
    }

    // Print timing (seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
